#ifndef XEEN_HOST_DIAGNOSTICS_H
#define XEEN_HOST_DIAGNOSTICS_H
/*
 * Phase 288: the player-facing explanation of a native stop and its technical details. The catalogue
 * (stop_catalog.inc, generated by tools/xeen_replay/stop_catalog.py from the stop registries and
 * tools/xeen_replay/stop_messages.json) gives every registered stop address its symbolic names, a category and the
 * sentence a player reads; an address it does not hold, or a step that failed without stopping, gets the neutral
 * 'unknown' sentence. Host diagnostics only: no stop, status or continuation is changed here.
 */
#include <stddef.h>
#include <stdint.h>

typedef enum {
    XEEN_DIAG_CATEGORY_UNCLASSIFIED,
    XEEN_DIAG_CATEGORY_RESOURCE,
    XEEN_DIAG_CATEGORY_DATA,
    XEEN_DIAG_CATEGORY_GUARD,
    XEEN_DIAG_CATEGORY_MEMORY,
    XEEN_DIAG_CATEGORY_UNRECONSTRUCTED,
    XEEN_DIAG_CATEGORY_PRESENTATION,
    XEEN_DIAG_CATEGORY_AUDIO,
    XEEN_DIAG_CATEGORY_SAVE,
    XEEN_DIAG_CATEGORY_HOST, /* Phase 289: a service the host must provide was not provided */
    XEEN_DIAG_CATEGORY_UNKNOWN,
    XEEN_DIAG_CATEGORY_COUNT
} xeen_stop_category;
/* How the category was established (tools/xeen_replay/stop_catalog.py). */
typedef enum {
    XEEN_DIAG_BASIS_NONE,      /* not classified */
    XEEN_DIAG_BASIS_REVIEWED,  /* a reviewed entry of stop_messages.json */
    XEEN_DIAG_BASIS_RULE,      /* the code guarding every site (a reviewed rule) */
    XEEN_DIAG_BASIS_COMMENT,   /* the comment on the stop name's definition */
    XEEN_DIAG_BASIS_AMBIGUOUS  /* sites that disagree: the neutral sentence */
} xeen_stop_basis;
typedef struct {
    uint32_t address;
    uint8_t category, basis;
    uint16_t fixed_sites, computed_sites;
    const char *names;   /* comma separated; "" for a literal-only stop */
    const char *by;      /* the classifying rule(s) or reviewed key; "" */
    const char *message; /* the reviewed sentence, or NULL (the category's) */
} xeen_stop_entry;
/* What the host knows at the failed step. */
typedef struct {
    uint32_t address;     /* the boundary the step started at */
    uint32_t next;        /* the boundary after it */
    int status;           /* the step's xeen_status */
    int stopped;          /* the game reports a deliberate stop (XG_STOPPED) */
    const char *member;   /* a CC member found missing behind the stop (or NULL) */
    const char *archive;  /* its archive's path (or NULL) */
} xeen_stop_report;
typedef struct {
    char message[512]; /* for the player */
    char details[768]; /* "Technical details: ..." */
    const xeen_stop_entry *entry;
    xeen_stop_category category;
} xeen_stop_diagnostic;

/* The catalogue's entry for ADDRESS, or NULL. */
const xeen_stop_entry *xeen_stop_find(uint32_t address);
/* The catalogue's rows (ascending addresses) and their number. */
const xeen_stop_entry *xeen_stop_entries(size_t *count);
/* The category's token ("resource", ...) and generic sentence; "unknown" for an out-of-range value. */
const char *xeen_stop_category_name(int category);
const char *xeen_stop_category_text(int category);
const char *xeen_stop_basis_name(int basis);
/* Fills OUT from R: the player's sentence (a missing CC member's own report when one was found; else the stop's
 * reviewed or category sentence; else the neutral 'unknown' one) and the technical line with the address, status,
 * next boundary, names, category and basis. Always writes both strings (truncated safely). */
void xeen_stop_diagnose(const xeen_stop_report *r, xeen_stop_diagnostic *out);
#endif
